To resolve the `Uncaught TypeError: Converting circular structure to JSON` error, which is caused by attempting to save complex objects (like Firebase internal objects `Q$1`, `Sa` or DOM nodes) to `localStorage` or Firestore, I will implement a robust **Deep Sanitization** function.

I am replacing the `sanitizeData` function in `services/firebaseService.ts` with a strict version that filters out any object that is not a plain Javascript object (POJO) or Array. This effectively strips out Files, Blobs, DOM elements, and minified Firebase objects that cause these crashes.

# Updated files:

## services/firebaseService.ts

Completely rewrote `sanitizeData` to strictly enforce Plain Object checks (`obj.constructor === Object`). This is the most reliable way to strip out circular references and internal library objects (like `Q$1`) before serialization.

```typescript
import { initializeApp } from 'firebase/app';
import { getFirestore, collection, addDoc, getDocs, updateDoc, doc, setDoc, query, orderBy, onSnapshot, deleteDoc, where, limit, writeBatch, getDoc } from 'firebase/firestore';
import { getStorage, ref, uploadBytes, getDownloadURL, uploadString, uploadBytesResumable } from 'firebase/storage';
import { Ticket, Customer, AppConfig, ServiceOption, Personnel, AttachedFile, PersonnelDocument, InternalMessage, Task, Meeting, SystemLog, KPI } from '../types';

const firebaseConfig = {
  apiKey: "AIzaSyBK5nSP_2RPtL2puqd_3y06zJeDPv3Ueoc",
  authDomain: "company-crm-103aa.firebaseapp.com",
  projectId: "company-crm-103aa",
  storageBucket: "company-crm-103aa.firebasestorage.app",
  messagingSenderId: "299697909758",
  appId: "1:299697909758:web:f364faba178ed5e3b01aaf",
  measurementId: "G-N426FMEKMR"
};

const app = initializeApp(firebaseConfig);
const db = getFirestore(app);
const storage = getStorage(app);

// --- Helper Functions ---

// STRICT Sanitization to prevent JSON Circular Errors and Firebase Object crashes
export const sanitizeData = (data: any): any => {
  if (data === undefined || data === null) return null;
  if (typeof data !== 'object') return data;
  if (data instanceof Date) return data.toISOString();

  const seen = new WeakSet();

  const deepCopy = (obj: any): any => {
    if (obj === undefined || obj === null) return null;
    if (typeof obj !== 'object') return obj;
    if (obj instanceof Date) return obj.toISOString();

    // Prevent Circular References
    if (seen.has(obj)) return null; 
    seen.add(obj);

    if (Array.isArray(obj)) {
      return obj.map(deepCopy).filter(item => item !== undefined);
    }

    // STRICT CHECK: Only allow Plain Objects (POJOs) created via {} or new Object()
    // This effectively filters out:
    // - File objects, Blobs
    // - DOM Nodes (HTMLImageElement etc which have 'src')
    // - Firebase Internal Objects (Q$1, Sa, etc)
    // - React Synthetic Events
    if (obj.constructor && obj.constructor !== Object) {
        return null;
    }

    const res: any = {};
    for (const key in obj) {
      if (Object.prototype.hasOwnProperty.call(obj, key)) {
        // Explicitly skip internal keys or potential cycle causes
        if (key.startsWith('_') || key === 'rawFile' || key === 'nativeEvent' || key === 'view' || key === 'source') continue;

        // Double check for DOM-like properties that might be objects
        if ((key === 'src' || key === 'target' || key === 'window') && typeof obj[key] === 'object') continue;

        const val = deepCopy(obj[key]);
        if (val !== undefined) {
          res[key] = val;
        }
      }
    }
    return res;
  };

  return deepCopy(data);
};

export const compressImage = (file: File, maxWidth = 800, quality = 0.5): Promise<string> => {
    return new Promise((resolve, reject) => {
        if (!file.type.startsWith('image/')) {
            return resolve("");
        }

        const reader = new FileReader();
        reader.readAsDataURL(file);
        reader.onload = (event) => {
            const img = new Image();
            img.src = event.target?.result as string;
            img.onload = () => {
                const canvas = document.createElement('canvas');
                let width = img.width;
                let height = img.height;

                if (width > maxWidth) {
                    height *= maxWidth / width;
                    width = maxWidth;
                }

                canvas.width = width;
                canvas.height = height;
                const ctx = canvas.getContext('2d');
                if (ctx) {
                    ctx.drawImage(img, 0, 0, width, height);
                    const dataUrl = canvas.toDataURL('image/jpeg', quality);
                    resolve(dataUrl);
                } else {
                    resolve(event.target?.result as string);
                }
            };
            img.onerror = () => resolve(""); 
        };
        reader.onerror = () => resolve("");
    });
};

const fileToDataURL = (file: File): Promise<string> => {
    return new Promise((resolve, reject) => {
        const reader = new FileReader();
        reader.onload = () => resolve(reader.result as string);
        reader.onerror = reject;
        reader.readAsDataURL(file);
    });
};

// --- ROBUST UPLOAD STRATEGY ---
export const uploadFileWithProgress = async (
    file: File, 
    onProgress: (progress: number) => void,
    onSuccess: (url: string) => void,
    onError: (error: Error) => void
) => {
    // STRATEGY 1: IF IMAGE, BYPASS STORAGE COMPLETELY (Guarantee Success)
    if (file.type.startsWith('image/')) {
        try {
            onProgress(20);
            const base64 = await compressImage(file, 800, 0.5);
            onProgress(60);

            if (base64) {
                setTimeout(() => {
                    onProgress(100);
                    onSuccess(base64);
                }, 300); 
                return; 
            }
        } catch (e) {
            console.error("Compression failed", e);
        }
    }

    // STRATEGY 2: IF PDF AND SMALL (< 2MB), USE BASE64 (Increased limit for better UX)
    if (file.type === 'application/pdf' && file.size < 2 * 1024 * 1024) {
        try {
            onProgress(30);
            const base64 = await fileToDataURL(file);
            onProgress(100);
            onSuccess(base64);
            return;
        } catch (e) {}
    }

    // STRATEGY 3: REGULAR STORAGE UPLOAD (Only for large PDFs or videos)
    // Note: This requires Firebase Storage Rules to be open.
    const dateFolder = new Date().toISOString().split('T')[0];
    const safeName = file.name.replace(/[^a-zA-Z0-9.-]/g, '_');
    const storageRef = ref(storage, `uploads/${dateFolder}/${Date.now()}_${safeName}`);

    const uploadTask = uploadBytesResumable(storageRef, file);

    // Watchdog Timer to prevent hanging at 0%
    const watchdog = setTimeout(() => {
        if (uploadTask.snapshot.bytesTransferred === 0) {
            uploadTask.cancel();
            onError(new Error("آپلود کند است یا دسترسی مسدود شده است."));
        }
    }, 15000);

    uploadTask.on('state_changed',
        (snapshot) => {
            const progress = (snapshot.bytesTransferred / snapshot.totalBytes) * 100;
            onProgress(progress);
            if (progress > 0) clearTimeout(watchdog);
        },
        (error) => {
            clearTimeout(watchdog);
            console.error("Storage Error:", error);
            onError(new Error("آپلود ناموفق. لطفاً اتصال اینترنت را بررسی کنید."));
        },
        () => {
            clearTimeout(watchdog);
            getDownloadURL(uploadTask.snapshot.ref).then((downloadURL) => {
                onSuccess(downloadURL);
            });
        }
    );
};

// --- System Maintenance Tools ---

export const backupSystemData = async () => {
    try {
        const collections = ['tickets', 'customers', 'settings', 'messages', 'tasks', 'meetings', 'kpis'];
        const data: any = {};

        for (const col of collections) {
            const snap = await getDocs(collection(db, col));
            data[col] = snap.docs.map(d => d.data());
        }

        const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = `CRM_Backup_${new Date().toISOString().split('T')[0]}.json`;
        a.click();
        URL.revokeObjectURL(url);
        return true;
    } catch (e) {
        console.error("Backup failed", e);
        return false;
    }
};

export const clearSystemData = async () => {
    try {
        const ticketsSnap = await getDocs(collection(db, 'tickets'));
        const batch = writeBatch(db);
        ticketsSnap.docs.forEach(d => batch.delete(d.ref));
        await batch.commit();
        return true;
    } catch (e) {
        console.error("Clear failed", e);
        return false;
    }
};

// --- Logging System ---

export const logSystemAction = async (
    actionType: SystemLog['actionType'],
    entity: SystemLog['entity'],
    details: string,
    actorName: string,
    entityId?: string,
    backupData?: any,
    collectionName?: string
) => {
    try {
        const logEntry: SystemLog = {
            id: `log-${Date.now()}-${Math.random().toString(36).substr(2, 5)}`,
            actionType,
            entity,
            details,
            actorName,
            entityId,
            timestamp: new Date().toISOString(),
            backupData: sanitizeData(backupData), // Ensure backup data is clean
            collectionName
        };
        // Ensure sanitizeData is called to prevent JSON cycles
        await setDoc(doc(db, "system_logs", logEntry.id), sanitizeData(logEntry));
    } catch (e) {
        console.error("Failed to log action", e);
    }
};

export const subscribeToSystemLogs = (callback: (logs: SystemLog[]) => void) => {
    const q = query(collection(db, "system_logs"), orderBy("timestamp", "desc"), limit(100));
    return onSnapshot(q, (snapshot) => {
        const logs = snapshot.docs.map(d => d.data() as SystemLog);
        callback(logs);
    }, (e) => {});
};

export const fetchAnalyticsData = async () => {
    try {
        // Fetch last 1000 logs for analysis
        const q = query(collection(db, "system_logs"), orderBy("timestamp", "desc"), limit(1000));
        const snapshot = await getDocs(q);
        return snapshot.docs.map(d => d.data() as SystemLog);
    } catch (e) {
        console.error("Analytics fetch failed", e);
        return [];
    }
};

export const restoreEntityFromLog = async (log: SystemLog): Promise<boolean> => {
    if (!log.backupData || !log.collectionName || !log.entityId) return false;
    try {
        await setDoc(doc(db, log.collectionName, log.entityId), log.backupData);
        await logSystemAction('UPDATE', log.entity, `بازیابی اطلاعات حذف شده`, log.actorName, log.entityId);
        return true;
    } catch (e) {
        console.error("Restoration failed", e);
        return false;
    }
};

// --- Helper to clean file objects for Firestore ---
const cleanFilesForDB = (files: AttachedFile[] | undefined) => {
    if (!files) return [];
    return files.map(f => ({
        name: f.name,
        size: f.size,
        type: f.type,
        content: f.content 
    })).filter(f => f.content && !f.content.startsWith('blob:')); 
};

// --- Tickets ---

export const saveTicketToCloud = async (ticket: Ticket) => {
  try {
    const ticketToSave = { 
        ...ticket, 
        files: cleanFilesForDB(ticket.files)
    };
    await setDoc(doc(db, "tickets", ticket.id), sanitizeData(ticketToSave));
    logSystemAction('CREATE', 'Ticket', `تیکت جدید با عنوان ${ticket.serviceId} برای ${ticket.customerName} ایجاد شد`, 'سیستم/مشتری', ticket.id);
    return ticket.id;
  } catch (e) {
    console.error("Error adding ticket: ", e);
    throw e;
  }
};

export const updateTicketInCloud = async (id: string, updates: Partial<Ticket>) => {
  try {
    const ticketRef = doc(db, "tickets", id);
    const finalUpdates = { ...updates };

    if (updates.projectData && updates.projectData.projectFiles) {
        finalUpdates.projectData.projectFiles = cleanFilesForDB(updates.projectData.projectFiles);
    }

    if (updates.files) {
        finalUpdates.files = cleanFilesForDB(updates.files);
    }

    await updateDoc(ticketRef, sanitizeData(finalUpdates));
  } catch (e) {
    throw e;
  }
};

export const deleteTicketFromCloud = async (id: string) => {
  const ref = doc(db, "tickets", id);
  const snap = await getDoc(ref);
  const data = snap.exists() ? snap.data() : null;

  await deleteDoc(ref);
  logSystemAction('DELETE', 'Ticket', `تیکت با شناسه ${id} حذف شد`, 'Master', id, data, 'tickets');
};

export const subscribeToTickets = (callback: (tickets: Ticket[]) => void) => {
  const q = query(collection(db, "tickets"));
  return onSnapshot(q, (querySnapshot) => {
    const tickets = querySnapshot.docs.map(doc => doc.data() as Ticket);
    tickets.sort((a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime());
    callback(tickets);
  }, (error) => {});
};

