// STRICT Sanitization to prevent JSON Circular Errors and Firebase Object crashes
export const sanitizeData = (data: any): any => {
  if (data === undefined || data === null) return null;
  if (typeof data !== 'object') return data;
  if (data instanceof Date) return data.toISOString();

  const seen = new WeakSet();

  const deepCopy = (obj: any): any => {
    if (obj === undefined || obj === null) return null;
    if (typeof obj !== 'object') return obj;
    if (obj instanceof Date) return obj.toISOString();

    // Prevent Circular References
    if (seen.has(obj)) return null; 
    seen.add(obj);

    if (Array.isArray(obj)) {
      return obj.map(deepCopy).filter(item => item !== undefined);
    }

    // STRICT CHECK: Only allow Plain Objects (POJOs) created via {} or new Object()
    // This effectively filters out:
    // - File objects, Blobs
    // - DOM Nodes (HTMLImageElement etc which have 'src')
    // - Firebase Internal Objects (Q$1, Sa, etc)
    // - React Synthetic Events
    if (obj.constructor && obj.constructor !== Object) {
        return null;
    }

    const res: any = {};
    for (const key in obj) {
      if (Object.prototype.hasOwnProperty.call(obj, key)) {
        // Explicitly skip internal keys or potential cycle causes
        if (key.startsWith('_') || key === 'rawFile' || key === 'nativeEvent' || key === 'view' || key === 'source') continue;

        // Double check for DOM-like properties that might be objects
        if ((key === 'src' || key === 'target' || key === 'window') && typeof obj[key] === 'object') continue;

        const val = deepCopy(obj[key]);
        if (val !== undefined) {
          res[key] = val;
        }
      }
    }
    return res;
  };

  return deepCopy(data);
};

export const compressImage = (file: File, maxWidth = 800, quality = 0.5): Promise<string> => {
    return new Promise((resolve, reject) => {
        if (!file.type.startsWith('image/')) {
            return resolve("");
        }

        const reader = new FileReader();
        reader.readAsDataURL(file);
        reader.onload = (event) => {
            const img = new Image();
            img.src = event.target?.result as string;
            img.onload = () => {
                const canvas = document.createElement('canvas');
                let width = img.width;
                let height = img.height;

                if (width > maxWidth) {
                    height *= maxWidth / width;
                    width = maxWidth;
                }

                canvas.width = width;
                canvas.height = height;
                const ctx = canvas.getContext('2d');
                if (ctx) {
                    ctx.drawImage(img, 0, 0, width, height);
                    const dataUrl = canvas.toDataURL('image/jpeg', quality);
                    resolve(dataUrl);
                } else {
                    resolve(event.target?.result as string);
                }
            };
            img.onerror = () => resolve(""); 
        };
        reader.onerror = () => resolve("");
    });
};

const fileToDataURL = (file: File): Promise<string> => {
    return new Promise((resolve, reject) => {
        const reader = new FileReader();
        reader.onload = () => resolve(reader.result as string);
        reader.onerror = reject;
        reader.readAsDataURL(file);
    });
};

